CREATE COLUMN TABLE "TEST_AP"."CSHS" ("FormID" NVARCHAR(100) NOT NULL , "ItemID" NVARCHAR(52) NOT NULL , "ColID" NVARCHAR(128) DEFAULT '-1' NOT NULL , "ActionT" SMALLINT CS_INT DEFAULT 0, "QueryId" INTEGER CS_INT, "IndexID" INTEGER CS_INT NOT NULL , "Refresh" NVARCHAR(1) DEFAULT 'N', "FieldID" NVARCHAR(60), "FrceRfrsh" NVARCHAR(1) DEFAULT 'N', "ByField" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("IndexID")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "CSHS_DETAILS" ON "TEST_AP"."CSHS" ( "FormID" ASC, "ItemID" ASC, "ColID" ASC )